const t=JSON.parse('[{"topic":"positionMovement","en":{"q":"What is <strong>distance</strong>?","a":"The <strong>total path length</strong> travelled by an object (scalar)."},"zhHant":{"q":"甚麼是<strong>路程</strong>？","a":"物體所走的<strong>路徑總長度</strong>（標量）。"}},{"topic":"positionMovement","en":{"q":"What is <strong>displacement</strong>?","a":"The straight-line length from start to finish <strong>in a specified direction</strong> (vector)."},"zhHant":{"q":"甚麼是<strong>位移</strong>？","a":"起點到終點的直線長度，並有<strong>指定方向</strong>（矢量）。"}},{"topic":"positionMovement","en":{"q":"How do you define average speed and average velocity?","a":"Average speed = <strong>total distance / total time</strong>. Average velocity = <strong>displacement / total time</strong>."},"zhHant":{"q":"平均速率和平均速度怎樣定義？","a":"平均速率 = <strong>總路程 / 總時間</strong>。平均速度 = <strong>位移 / 總時間</strong>。"}},{"topic":"positionMovement","en":{"q":"What is a scalar? Give examples.","a":"A quantity with <strong>magnitude only</strong> (no direction). Examples: time, mass, distance, speed."},"zhHant":{"q":"甚麼是標量？舉例說明。","a":"只有<strong>大小、沒有方向</strong>的物理量。例：時間、質量、路程、速率。"}},{"topic":"positionMovement","en":{"q":"What is a vector? Give examples.","a":"A quantity with <strong>magnitude and direction</strong>. Examples: displacement, velocity, acceleration, force."},"zhHant":{"q":"甚麼是矢量？舉例說明。","a":"同時有<strong>大小和方向</strong>的物理量。例：位移、速度、加速度、力。"}},{"topic":"equationOfMotion","en":{"q":"When does an object have acceleration?","a":"When its <strong>speed changes</strong> and/or its <strong>direction of motion</strong> changes."},"zhHant":{"q":"物體何時有加速度？","a":"當<strong>速率改變</strong>和／或<strong>運動方向改變</strong>時。"}},{"topic":"equationOfMotion","en":{"q":"Write the equation linking <strong>u, v, a, t</strong>.","a":"<strong>v = u + at</strong>"},"zhHant":{"q":"寫出聯繫 <strong>u、v、a、t</strong> 的方程。","a":"<strong>v = u + at</strong>"}},{"topic":"equationOfMotion","en":{"q":"Write the equation linking <strong>s, u, a, t</strong>.","a":"<strong>s = ut + ½at²</strong>"},"zhHant":{"q":"寫出聯繫 <strong>s、u、a、t</strong> 的方程。","a":"<strong>s = ut + ½at²</strong>"}},{"topic":"equationOfMotion","en":{"q":"Write the equation linking <strong>v, u, a, s</strong> (no time).","a":"<strong>v² = u² + 2as</strong>"},"zhHant":{"q":"寫出聯繫 <strong>v、u、a、s</strong>（不含時間）的方程。","a":"<strong>v² = u² + 2as</strong>"}},{"topic":"equationOfMotion","en":{"q":"Write the equation linking <strong>s, u, v, t</strong> (no acceleration).","a":"<strong>s = (u + v)t / 2</strong>"},"zhHant":{"q":"寫出聯繫 <strong>s、u、v、t</strong>（不含加速度）的方程。","a":"<strong>s = (u + v)t / 2</strong>"}},{"topic":"verticalMotion","en":{"q":"What is the acceleration of free fall (neglecting air resistance)?","a":"<strong>a = g ≈ 9.81 m s⁻²</strong>, always <strong>vertically downward</strong>."},"zhHant":{"q":"自由落體的加速度是甚麼（忽略空氣阻力）？","a":"<strong>a = g ≈ 9.81 m s⁻²</strong>，方向<strong>永遠向下</strong>。"}},{"topic":"verticalMotion","en":{"q":"Does free-fall acceleration depend on mass or release height?","a":"<strong>No</strong> — neglecting air resistance, <strong>a = g</strong> for all masses and heights."},"zhHant":{"q":"自由落體加速度會因質量或釋放高度而改變嗎？","a":"<strong>不會</strong>——忽略空氣阻力時，任何質量和高度都是 <strong>a = g</strong>。"}},{"topic":"verticalMotion","en":{"q":"At the highest point of a vertical throw, what are <strong>v</strong> and <strong>a</strong>?","a":"<strong>v = 0</strong>, but <strong>a = g downward</strong> (acceleration is never zero)."},"zhHant":{"q":"竖直上拋至最高點時，<strong>v</strong> 和 <strong>a</strong> 分別是甚麼？","a":"<strong>v = 0</strong>，但 <strong>a = g 向下</strong>（加速度永不為零）。"}},{"topic":"verticalMotion","en":{"q":"In a vacuum, how do a coin and a feather fall?","a":"They fall <strong>at the same rate</strong> (same acceleration g)."},"zhHant":{"q":"在真空中，硬幣和羽毛怎樣下落？","a":"它們以<strong>相同速率</strong>下落（相同加速度 g）。"}},{"topic":"verticalMotion","en":{"q":"For vertical motion under gravity only, how does velocity change with time?","a":"Velocity <strong>increases uniformly</strong> downward (constant acceleration g)."},"zhHant":{"q":"只受重力的豎直運動中，速度怎樣隨時間改變？","a":"速度向下<strong>均勻增加</strong>（加速度 g 恆定）。"}},{"topic":"motionGraph","en":{"q":"What does the <strong>slope of an s–t graph</strong> equal?","a":"<strong>Velocity (v)</strong>"},"zhHant":{"q":"<strong>s–t 圖的斜率</strong>代表甚麼？","a":"<strong>速度 (v)</strong>"}},{"topic":"motionGraph","en":{"q":"What does the <strong>slope of a v–t graph</strong> equal?","a":"<strong>Acceleration (a)</strong>"},"zhHant":{"q":"<strong>v–t 圖的斜率</strong>代表甚麼？","a":"<strong>加速度 (a)</strong>"}},{"topic":"motionGraph","en":{"q":"What does the <strong>area under a v–t graph</strong> equal?","a":"<strong>Displacement (s)</strong>"},"zhHant":{"q":"<strong>v–t 圖下方的面積</strong>代表甚麼？","a":"<strong>位移 (s)</strong>"}},{"topic":"motionGraph","en":{"q":"What does the <strong>area under an a–t graph</strong> equal?","a":"<strong>Change of velocity (Δv)</strong>"},"zhHant":{"q":"<strong>a–t 圖下方的面積</strong>代表甚麼？","a":"<strong>速度變化量 (Δv)</strong>"}},{"topic":"motionGraph","en":{"q":"On a v–t graph, when does the object reverse direction?","a":"When the graph <strong>crosses the time axis</strong> (velocity changes sign)."},"zhHant":{"q":"在 v–t 圖上，物體何時反向？","a":"當圖線<strong>穿過時間軸</strong>（速度變號）時。"}},{"topic":"forceI","en":{"q":"State Newton’s first law.","a":"An object remains at rest or moves with <strong>uniform velocity</strong> unless acted on by a <strong>net force</strong>."},"zhHant":{"q":"寫出牛頓第一定律。","a":"除非受到<strong>淨力</strong>作用，物體保持靜止或以<strong>勻速</strong>運動。"}},{"topic":"forceI","en":{"q":"What is <strong>inertia</strong>?","a":"The tendency of an object to <strong>remain at rest or keep moving at uniform velocity</strong>. Greater mass → greater inertia."},"zhHant":{"q":"甚麼是<strong>慣性</strong>？","a":"物體<strong>保持靜止或以勻速運動</strong>的傾向。質量越大，慣性越大。"}},{"topic":"forceI","en":{"q":"State Newton’s second law and its formula.","a":"Acceleration is proportional to net force and inversely proportional to mass: <strong>F<sub>net</sub> = ma</strong>."},"zhHant":{"q":"寫出牛頓第二定律及其公式。","a":"加速度與淨力成正比，與質量成反比：<strong>F<sub>net</sub> = ma</strong>。"}},{"topic":"forceI","en":{"q":"What is the formula for <strong>weight</strong>?","a":"<strong>W = mg</strong>"},"zhHant":{"q":"<strong>重量</strong>的公式是甚麼？","a":"<strong>W = mg</strong>"}},{"topic":"forceI","en":{"q":"What is Newton’s third law (action–reaction)?","a":"Forces come in pairs: if A exerts a force on B, B exerts an <strong>equal and opposite</strong> force on A."},"zhHant":{"q":"牛頓第三定律（作用力與反作用力）是甚麼？","a":"力成對出現：若 A 對 B 施力，B 對 A 施<strong>大小相等、方向相反</strong>的力。"}},{"topic":"forceII","en":{"q":"How do you resolve a force F at angle θ into components?","a":"<strong>F<sub>x</sub> = F cos θ</strong> (horizontal), <strong>F<sub>y</sub> = F sin θ</strong> (vertical)."},"zhHant":{"q":"怎樣把與水平成 θ 角的力 F 分解？","a":"<strong>F<sub>x</sub> = F cos θ</strong>（水平），<strong>F<sub>y</sub> = F sin θ</strong>（豎直）。"}},{"topic":"forceII","en":{"q":"Why resolve forces into perpendicular components?","a":"Perpendicular components can be treated <strong>independently</strong>."},"zhHant":{"q":"為甚麼要把力分解成互相垂直的分量？","a":"互相垂直的分量可以<strong>獨立處理</strong>。"}},{"topic":"forceII","en":{"q":"For an object hung by two strings in equilibrium, what balances the weight?","a":"The <strong>vertical components of the tensions</strong> add up to the weight."},"zhHant":{"q":"物體被兩條繩懸掛並平衡時，甚麼平衡重量？","a":"兩條繩張力的<strong>豎直分量之和</strong>等於重量。"}},{"topic":"forceII","en":{"q":"A block is pulled by force F at angle θ on a horizontal surface. What is the horizontal driving force?","a":"<strong>F cos θ</strong> (minus friction if present)."},"zhHant":{"q":"物塊被與水平成 θ 的力 F 拉動。水平推動力是甚麼？","a":"<strong>F cos θ</strong>（若有摩擦再減去摩擦力）。"}},{"topic":"forceII","en":{"q":"On a free-body diagram, where do you draw weight and normal reaction?","a":"Weight from the <strong>centre</strong>; normal reaction from the <strong>contact surface</strong>, perpendicular to it."},"zhHant":{"q":"自由體圖中，重量和法向力怎樣畫？","a":"重量從<strong>物體中心</strong>畫出；法向力從<strong>接觸面</strong>垂直畫出。"}},{"topic":"forceIII","en":{"q":"In a lift at rest or moving at constant velocity, how does scale reading R compare with weight mg?","a":"<strong>R = mg</strong> (normal weight)."},"zhHant":{"q":"升降機靜止或勻速運動時，磅秤讀數 R 與重量 mg 的關係？","a":"<strong>R = mg</strong>（正常重量感覺）。"}},{"topic":"forceIII","en":{"q":"When does a person in a lift feel heavier than usual?","a":"When the lift has <strong>upward acceleration</strong> (or decelerates while going down): <strong>R > mg</strong>."},"zhHant":{"q":"升降機中的人何時感覺比平常重？","a":"升降機有<strong>向上加速度</strong>（或下降時減速）時：<strong>R > mg</strong>。"}},{"topic":"forceIII","en":{"q":"When does a person in a lift feel lighter than usual?","a":"When the lift has <strong>downward acceleration</strong> (or decelerates while going up): <strong>R < mg</strong>."},"zhHant":{"q":"升降機中的人何時感覺比平常輕？","a":"升降機有<strong>向下加速度</strong>（或上升時減速）時：<strong>R < mg</strong>。"}},{"topic":"forceIII","en":{"q":"What happens to the scale reading in a freely falling lift?","a":"<strong>R = 0</strong> — the person feels <strong>weightless</strong>."},"zhHant":{"q":"自由落體的升降機中，磅秤讀數怎樣？","a":"<strong>R = 0</strong>——人感覺<strong>失重</strong>。"}},{"topic":"forceIII","en":{"q":"For upward acceleration a in a lift, what is the scale reading R?","a":"<strong>R − mg = ma</strong> ⇒ <strong>R = m(g + a)</strong>"},"zhHant":{"q":"升降機向上加速度為 a 時，磅秤讀數 R 是甚麼？","a":"<strong>R − mg = ma</strong> ⇒ <strong>R = m(g + a)</strong>"}},{"topic":"moment","en":{"q":"What is the <strong>moment (torque)</strong> of a force about a point?","a":"The <strong>turning effect</strong> of the force about that point. Unit: <strong>N m</strong>."},"zhHant":{"q":"力對一點的<strong>力矩（轉矩）</strong>是甚麼？","a":"力對該點的<strong>轉動效應</strong>。單位：<strong>N m</strong>。"}},{"topic":"moment","en":{"q":"Write the formula for moment of a force.","a":"<strong>Moment = F × d<sub>⊥</sub></strong> = <strong>Fd sin θ</strong>"},"zhHant":{"q":"寫出力矩公式。","a":"<strong>力矩 = F × d<sub>⊥</sub></strong> = <strong>Fd sin θ</strong>"}},{"topic":"moment","en":{"q":"When is the moment of a force zero?","a":"When the <strong>perpendicular distance</strong> is zero (line of action through the pivot), or θ = 0° / 180°."},"zhHant":{"q":"何時力矩為零？","a":"當<strong>垂直距離</strong>為零（作用線過支點），或 θ = 0°／180°。"}},{"topic":"moment","en":{"q":"State the <strong>principle of moments</strong>.","a":"For balance: <strong>sum of clockwise moments = sum of anticlockwise moments</strong>."},"zhHant":{"q":"寫出<strong>力矩原理</strong>。","a":"平衡時：<strong>順時針力矩總和 = 逆時針力矩總和</strong>。"}},{"topic":"moment","en":{"q":"In which directions can a moment act?","a":"<strong>Clockwise</strong> or <strong>anticlockwise</strong>."},"zhHant":{"q":"力矩可以有哪些方向？","a":"<strong>順時針</strong>或<strong>逆時針</strong>。"}},{"topic":"workEnergyPower","en":{"q":"What is the formula for work done by a force?","a":"<strong>W = Fs cos θ</strong> (θ = angle between F and s). Unit: J."},"zhHant":{"q":"力做功的公式是甚麼？","a":"<strong>W = Fs cos θ</strong>（θ 為 F 與 s 的夾角）。單位：J。"}},{"topic":"workEnergyPower","en":{"q":"When is no work done by a force?","a":"When <strong>F is perpendicular to displacement</strong> (θ = 90°, cos θ = 0)."},"zhHant":{"q":"何時力不做功？","a":"當<strong>力與位移垂直</strong>（θ = 90°，cos θ = 0）時。"}},{"topic":"workEnergyPower","en":{"q":"Write the formulas for KE and GPE.","a":"<strong>KE = ½mv²</strong>, <strong>GPE = mgh</strong>"},"zhHant":{"q":"寫出動能和重力勢能公式。","a":"<strong>KE = ½mv²</strong>，<strong>GPE = mgh</strong>"}},{"topic":"workEnergyPower","en":{"q":"State the law of conservation of energy.","a":"Energy cannot be created or destroyed; it can only <strong>change form</strong>."},"zhHant":{"q":"寫出能量守恆定律。","a":"能量不能被創造或消滅，只能<strong>轉換形式</strong>。"}},{"topic":"workEnergyPower","en":{"q":"What is total mechanical energy?","a":"<strong>TE = KE + PE</strong> (conserved if no non-conservative work, e.g. negligible air resistance)."},"zhHant":{"q":"甚麼是總機械能？","a":"<strong>TE = KE + PE</strong>（若無視非守恆力做功，例如可忽略空氣阻力，則守恆）。"}},{"topic":"workEnergyPower","en":{"q":"How is average power calculated?","a":"<strong>P = W / t</strong> (work done per unit time). Unit: W (watt)."},"zhHant":{"q":"平均功率怎樣計算？","a":"<strong>P = W / t</strong>（單位時間做的功）。單位：W（瓦）。"}},{"topic":"momentum","en":{"q":"What is the formula for momentum?","a":"<strong>p = mv</strong> (vector). Unit: kg m s⁻¹."},"zhHant":{"q":"動量的公式是甚麼？","a":"<strong>p = mv</strong>（矢量）。單位：kg m s⁻¹。"}},{"topic":"momentum","en":{"q":"What is impulse, and how is it related to momentum?","a":"Impulse = <strong>FΔt = Δp</strong> (change in momentum)."},"zhHant":{"q":"甚麼是衝量？它與動量有何關係？","a":"衝量 = <strong>FΔt = Δp</strong>（動量變化）。"}},{"topic":"momentum","en":{"q":"State conservation of momentum.","a":"In an isolated system (no external net force), <strong>total momentum before = total momentum after</strong>."},"zhHant":{"q":"寫出動量守恆定律。","a":"在隔離系統（沒有外來淨力）中，<strong>碰撞前總動量 = 碰撞後總動量</strong>。"}},{"topic":"momentum","en":{"q":"For a perfectly inelastic collision (objects stick together), what is conserved?","a":"<strong>Momentum</strong> is conserved; kinetic energy is <strong>not</strong> fully conserved."},"zhHant":{"q":"完全非彈性碰撞（物體黏在一起）中，甚麼守恆？","a":"<strong>動量</strong>守恆；動能<strong>不完全</strong>守恆。"}},{"topic":"momentum","en":{"q":"A ball rebounds from a wall. Why is Δp large?","a":"Velocity reverses, so <strong>Δp = m(v_after − v_before)</strong> includes a large direction change."},"zhHant":{"q":"球撞牆反彈時，為甚麼動量變化 Δp 可以很大？","a":"速度反向，所以 <strong>Δp = m(v_後 − v_前)</strong> 包含大幅方向改變。"}},{"topic":"projectileMotion","en":{"q":"Key idea of projectile motion?","a":"Horizontal and vertical motions are <strong>independent</strong>; only <strong>time</strong> is shared."},"zhHant":{"q":"拋體運動的關鍵概念是甚麼？","a":"水平與豎直運動<strong>互相獨立</strong>；只有<strong>時間</strong>相同。"}},{"topic":"projectileMotion","en":{"q":"For a horizontal projection, what are a<sub>x</sub> and a<sub>y</sub>?","a":"<strong>a<sub>x</sub> = 0</strong> (u<sub>x</sub> = v<sub>x</sub> constant); <strong>a<sub>y</sub> = g</strong> downward."},"zhHant":{"q":"水平拋射時，a<sub>x</sub> 和 a<sub>y</sub> 是甚麼？","a":"<strong>a<sub>x</sub> = 0</strong>（u<sub>x</sub> = v<sub>x</sub> 恆定）；<strong>a<sub>y</sub> = g</strong> 向下。"}},{"topic":"projectileMotion","en":{"q":"Why is horizontal velocity constant in projectile motion (no air resistance)?","a":"There is <strong>no horizontal force</strong> acting on the object."},"zhHant":{"q":"為甚麼拋體運動中水平速度恆定（無視空氣阻力）？","a":"物體<strong>不受水平力</strong>。"}},{"topic":"projectileMotion","en":{"q":"How do you find the resultant speed of a projectile?","a":"<strong>v = √(v<sub>x</sub>² + v<sub>y</sub>²)</strong>, and tan θ = v<sub>y</sub> / v<sub>x</sub>."},"zhHant":{"q":"怎樣求拋體的合速度？","a":"<strong>v = √(v<sub>x</sub>² + v<sub>y</sub>²)</strong>，且 tan θ = v<sub>y</sub> / v<sub>x</sub>。"}},{"topic":"projectileMotion","en":{"q":"What is the only force on a projectile in flight (neglecting air resistance)?","a":"Its <strong>weight</strong> (mg downward)."},"zhHant":{"q":"拋體飛行時（忽略空氣阻力）只受甚麼力？","a":"它的<strong>重量</strong>（mg 向下）。"}},{"topic":"circularMotion","en":{"q":"Write two formulas for centripetal force.","a":"<strong>F = mv² / r</strong> = <strong>mrω²</strong>"},"zhHant":{"q":"寫出向心力的兩個公式。","a":"<strong>F = mv² / r</strong> = <strong>mrω²</strong>"}},{"topic":"circularMotion","en":{"q":"How are angular speed ω and period T related?","a":"<strong>ω = 2π / T</strong>"},"zhHant":{"q":"角速度 ω 與週期 T 有何關係？","a":"<strong>ω = 2π / T</strong>"}},{"topic":"circularMotion","en":{"q":"In a conical pendulum, what provides the centripetal force?","a":"The <strong>horizontal component of tension</strong>."},"zhHant":{"q":"圓錐擺中，甚麼提供向心力？","a":"張力的<strong>水平分量</strong>。"}},{"topic":"circularMotion","en":{"q":"In a conical pendulum, what balances the weight?","a":"<strong>T cos θ = mg</strong> (vertical component of tension)."},"zhHant":{"q":"圓錐擺中，甚麼平衡重量？","a":"<strong>T cos θ = mg</strong>（張力的豎直分量）。"}},{"topic":"circularMotion","en":{"q":"Does centripetal force do work on an object in uniform circular motion?","a":"<strong>No</strong> — it is always perpendicular to the velocity, so speed (and KE) stay constant."},"zhHant":{"q":"勻速圓周運動中，向心力對物體做功嗎？","a":"<strong>不做</strong>——力永遠垂直於速度，所以速率（和動能）恆定。"}},{"topic":"gravitationalForce","en":{"q":"State Newton’s law of universal gravitation.","a":"Gravitational force is proportional to <strong>m₁m₂</strong> and inversely proportional to <strong>r²</strong>: <strong>F = Gm₁m₂ / r²</strong>."},"zhHant":{"q":"寫出牛頓萬有引力定律。","a":"引力與 <strong>m₁m₂</strong> 成正比，與 <strong>r²</strong> 成反比：<strong>F = Gm₁m₂ / r²</strong>。"}},{"topic":"gravitationalForce","en":{"q":"What is G, and what is its value?","a":"The universal gravitational constant: <strong>G = 6.67 × 10⁻¹¹ N m² kg⁻²</strong>."},"zhHant":{"q":"G 是甚麼？數值是多少？","a":"萬有引力常數：<strong>G = 6.67 × 10⁻¹¹ N m² kg⁻²</strong>。"}},{"topic":"gravitationalForce","en":{"q":"If the distance between two masses is halved, what happens to F?","a":"F becomes <strong>4 times</strong> larger (inverse-square law)."},"zhHant":{"q":"兩質量距離減半時，F 怎樣變？","a":"F 變為原來的<strong>4 倍</strong>（平方反比定律）。"}},{"topic":"gravitationalForce","en":{"q":"For a satellite in circular orbit, what provides the centripetal force?","a":"<strong>Gravitational force</strong>: GmM / r² = mv² / r."},"zhHant":{"q":"衛星作圓周軌道時，甚麼提供向心力？","a":"<strong>萬有引力</strong>：GmM / r² = mv² / r。"}},{"topic":"gravitationalForce","en":{"q":"Orbital speed of a satellite around a central mass M?","a":"<strong>v = √(GM / r)</strong> (depends on M and r, not on satellite mass m)."},"zhHant":{"q":"繞中心質量 M 的衛星軌道速率是甚麼？","a":"<strong>v = √(GM / r)</strong>（取決於 M 和 r，與衛星質量 m 無關）。"}}]');export{t as default};
